package muyon.rd.p05c

import java.nio.file.Path

fun main(args:Array<String>) {
    require(args.size==1);val fixtures=Path.of(args[0]);val domain=Domain("lab-store-1","lab-scope-1","lab-stream-1")
    var passed=0;var failed=0
    fun test(name:String,body:()->Unit){try{body();println("PASS $name");passed++}catch(e:Throwable){println("FAIL $name: ${e.message}");failed++}}
    fun session(seed:LabSeed=LabSeed.NORMAL,body:(CorePort,Controller)->Unit) {CorePort.open(seed,fixtures,Path.of("/tmp/rd-p05-jvm-output/actual-core-stderr.log")).use {p->body(p,Controller(p,Presentation(domain,"epoch-0")))}}
    test("actual snapshot updates UI supplier projection") {session {_,c->val r=c.read();check(r.kind=="snapshot");check(c.presentation.snapshot!=null && c.presentation.status=="snapshot")}}
    test("actual Rust preview/commit receipt updates UI without Kotlin normalization") {session {_,c->c.read();val input=Business("supplier-a","real-a","1","\uFEFF e\u0301 ");c.edit(input);val plan=c.preview();check(plan?.kind=="prepared");val effect=c.commit();check(effect?.kind=="committed");check(c.presentation.receipts["real-a"]?.get("normalized_name")=="é");check(c.presentation.snapshot?.get("suppliers")?.toString()?.contains("é")==true);check(c.presentation.draft==input.raw)}}
    test("actual lost reply remains unresolved across read/edit and read-only lookup recovers") {session(LabSeed.LOST_REPLY) {_,c->c.read();val input=Business("supplier-a","lost-a","1"," Raw ");c.edit(input);c.preview();val effect=c.commit();check(effect?.kind=="unknown");check(c.unresolved?.business==input);c.read();c.edit(Business("supplier-a","new-not-authorized","2","Other"));check(c.presentation.currentIntent==input.intent);check(c.commit()==null);val recovered=c.lookup();check(recovered?.kind=="committed");check(c.unresolved==null && c.presentation.receipts[input.intent]!=null);val after=c.read();check(after.snapshot?.get("cursor").objectValue()["seq"]=="1");check(c.presentation.draft==input.raw)}}
    test("same intent double tap does not send a second commit") {session {_,c->c.read();c.edit(Business("supplier-a","double-a","1","A"));c.preview();check(c.commit()?.kind=="committed");check(c.commit()==null)}}
    test("actual XML-before-trim and lone surrogate rejected without client rewriting") {session {port,c->c.read();for((i,raw) in listOf("\u000b A","\uD800").withIndex()){c.edit(Business("supplier-a","invalid-$i","1",raw));check(c.preview()?.kind=="rejected");check(c.commit()==null)};check(port.request("snapshot",domain,"epoch-0").snapshot?.get("cursor").objectValue()["seq"]=="0")}}
    test("actual u64 max decimal reaches Rust and conflicts without precision loss") {session {_,c->c.read();c.edit(Business("supplier-a","max-a","18446744073709551615","Name"));val reply=c.preview();check(reply?.kind=="conflict");check(c.presentation.status=="conflict")}}
    test("actual foreign scope rejected with zero effects and preserved raw") {session {port,c->c.read();c.edit(Business("supplier-a","scope-a","1"," Raw "));val before=c.presentation.snapshot;val reply=port.request("snapshot",domain.copy(scope="other"),"epoch-0");check(reply.kind=="rejected" && reply.wire["reason"]=="domain_mismatch");c.presentation.accept(reply);check(c.presentation.snapshot==before && c.presentation.draft==" Raw ");check(port.request("snapshot",domain,"epoch-0").snapshot?.get("cursor").objectValue()["seq"]=="0")}}
    test("actual CAS conflict preserves competing draft and current Rust record") {session {port,c->c.read();val other=Business("supplier-a","competitor","1","Other");val plan=port.request("preview",domain,"epoch-0",other.fields()).plan!!;c.edit(Business("supplier-a","mine","1"," Mine "));c.preview();check(port.request("commit",domain,"epoch-0",other.fields(plan.text("id"))).kind=="committed");val reply=c.commit();check(reply?.kind=="conflict" && c.presentation.draft==" Mine ");check(c.presentation.receipts["mine"]==null)}}
    test("actual Rust dedup returns original receipt and rejects altered intent payload") {session {port,_->val b=Business("supplier-a","dedup","1"," Name ");val plan=port.request("preview",domain,"epoch-0",b.fields()).plan!!;val one=port.request("commit",domain,"epoch-0",b.fields(plan.text("id")));val two=port.request("commit",domain,"epoch-0",b.fields(plan.text("id")));check(one.receipt==two.receipt && two.snapshot?.get("cursor").objectValue()["seq"]=="1");val changed=port.request("commit",domain,"epoch-0",b.copy(raw="Changed").fields(plan.text("id")));check(changed.kind=="conflict");check(port.request("snapshot",domain,"epoch-0").snapshot?.get("cursor").objectValue()["seq"]=="1")}}
    test("actual old receipt and epoch retained without regressing newer projection or raw") {session {port,c->c.read();val first=Business("supplier-a","first","1","First");c.edit(first);val firstPlan=c.preview()!!.plan!!;val held=c.commit()!!;c.reconnect("epoch-1");c.edit(Business("supplier-a","second","2","Second"));c.preview();val newer=c.commit()!!;check(newer.kind=="committed");val display=Presentation(domain,"epoch-1");display.currentIntent="future";display.draft=" Future raw ";display.accept(newer);display.accept(held,BoundPlan(domain,first,firstPlan));check(display.receipts[first.intent]!=null);check(display.snapshot?.get("cursor").objectValue()["seq"]=="2" && display.draft==" Future raw ");val staleLookup=port.request("lookup",domain,"epoch-0",first.fields(firstPlan.text("id")));check(staleLookup.kind=="committed" && staleLookup.admission=="stale");display.accept(staleLookup,BoundPlan(domain,first,firstPlan));check(display.snapshot?.get("cursor").objectValue()["seq"]=="2")}}
    test("actual missing lookup stays unknown and never writes") {session {port,_->val b=Business("supplier-a","not-dispatched","1","Raw");val reply=port.request("lookup",domain,"epoch-0",b.fields("unknown-plan"));check(reply.kind=="unknown" && reply.receipt==null);check(port.request("snapshot",domain,"epoch-0").snapshot?.get("cursor").objectValue()["seq"]=="0")}}
    test("actual invalid request fields and null return safe empty metadata") {session {port,_->val reply=port.sendFrame(mapOf("protocol" to 0,"request_id" to "bad-field","op" to "snapshot","domain" to domain.wire(),"display_epoch" to "epoch-0","raw_utf16" to null));check(reply.kind=="rejected" && reply.wire["reason"]=="invalid_request" && reply.wire["request_id"]=="" && reply.snapshot==null);check(port.request("snapshot",domain,"epoch-0").snapshot?.get("cursor").objectValue()["seq"]=="0")}}
    println("RESULT $passed passed / $failed failed");check(failed==0)
}
